// Player, weapon and infected actors
camera.position.set(0,1.68,4);scene.add(camera);let yaw=0,pitch=0;const weapon=new THREE.Group();camera.add(weapon);weapon.position.set(.32,-.29,-.58);weapon.rotation.set(-.04,-.04,0);
const gunBody=box(weapon,0,0,0,.16,.17,.48,mats.metal,true);box(weapon,0,.075,-.11,.105,.055,.34,mats.dark,true);box(weapon,0,-.11,.015,.115,.22,.13,mats.dark,true);box(weapon,0,-.08,-.06,.105,.04,.22,mats.metal);const muzzle=box(weapon,0,.005,-.27,.065,.06,.12,mats.dark);const sight=box(weapon,0,.105,-.18,.03,.035,.04,mats.metal);const muzzleFlash=new THREE.PointLight(0xffba70,0,4);weapon.add(muzzleFlash);
const skinMat=new THREE.MeshStandardMaterial({color:0x777566,roughness:.88});const clothMat=new THREE.MeshStandardMaterial({color:0x343b34,roughness:1});const tornMat=new THREE.MeshStandardMaterial({color:0x44332e,roughness:1});const eyeMat=new THREE.MeshBasicMaterial({color:0xd9a66a});
const zombies=[];function makeZombie(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const torso= new THREE.Mesh(new THREE.CapsuleGeometry(.29,.55,4,8),clothMat);torso.position.y=1.05;torso.castShadow=true;g.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.22,10,8),skinMat);head.position.set(0,1.62,-.04);head.castShadow=true;g.add(head);const jaw=box(g,0,1.48,-.16,.22,.09,.16,tornMat);for(let s of [-1,1]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.035,6,6),eyeMat);eye.position.set(s*.085,1.65,-.23);g.add(eye);const arm=new THREE.Group();arm.position.set(s*.34,1.28,-.04);const upper=new THREE.Mesh(new THREE.CapsuleGeometry(.095,.38,3,6),clothMat);upper.position.y=-.2;upper.rotation.z=s*.1;arm.add(upper);const hand=new THREE.Mesh(new THREE.SphereGeometry(.09,7,6),skinMat);hand.position.set(0,-.45,-.08);arm.add(hand);arm.rotation.z=s*.65;g.add(arm);g.userData['arm'+s]=arm;const leg=new THREE.Group();leg.position.set(s*.14,.74,.02);const thigh=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.38,3,6),tornMat);thigh.position.y=-.22;leg.add(thigh);g.add(leg);g.userData['leg'+s]=leg;}
// ragged wounds and a dark soaked shirt patch
const wound=new THREE.Mesh(new THREE.SphereGeometry(.105,7,6),mats.blood);wound.position.set(.12,1.1,-.28);g.add(wound);g.userData={...(g.userData||{}),health:100,speed:1.05+rand()*.32,phase:rand()*8,attack:0,dead:false};g.traverse(o=>{if(o.isMesh)o.castShadow=true;});zombies.push(g);return g;}
let keys={},ammo=12,reserve=48,health=100,stamina=100,wave=1,kills=0,reloading=false,reloadTime=0,shootCooldown=0,spawnTimer=1,playing=false,gameOver=false,hitTimer=0,walkTime=0,damageTimer=0;const pickups=[];const raycaster=new THREE.Raycaster();const clock=new THREE.Clock();
function spawnWave(){document.getElementById('waveNum').textContent=String(wave).padStart(2,'0');for(let i=0;i<Math.min(3+wave,8);i++){const angle=(rand()-.5)*1.5,x=(rand()-.5)*12,z=-15-rand()*45;makeZombie(x,z);}}
function ui(){document.getElementById('healthNum').textContent=Math.ceil(health);document.getElementById('healthBar').style.width=Math.max(0,health)+'%';document.getElementById('staminaNum').textContent=Math.ceil(stamina);document.getElementById('staminaBar').style.width=Math.max(0,stamina)+'%';document.getElementById('ammoNum').textContent=ammo;document.getElementById('reserveNum').textContent=reserve;}
function startGame(){if(playing)return;document.getElementById('startScreen').style.display='none';document.getElementById('endScreen').classList.remove('visible');document.getElementById('hud').style.display='block';playing=true;gameOver=false;health=100;stamina=100;ammo=12;reserve=48;wave=1;kills=0;camera.position.set(0,1.68,4);yaw=0;pitch=0;zombies.splice(0).forEach(z=>scene.remove(z));spawnWave();ui();renderer.domElement.requestPointerLock?.();}
document.getElementById('startBtn').addEventListener('click',startGame);document.getElementById('restartBtn').addEventListener('click',startGame);
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&playing&&!gameOver){document.getElementById('startScreen').style.display='flex';document.querySelector('.prompt-content .kicker').textContent='PAUSADO · TOQUE PARA CONTINUAR';document.getElementById('startBtn').textContent='VOLTAR AO JOGO ↗';playing=false;}});
document.addEventListener('mousemove',e=>{if(!playing||!document.pointerLockElement)return;yaw-=e.movementX*.0022;pitch-=e.movementY*.0022;pitch=Math.max(-1.35,Math.min(1.35,pitch));camera.rotation.set(pitch,yaw,0,'YXZ');});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='KeyR')reload();if(e.code==='KeyE')pickup();if(e.code==='Escape'&&playing){} });document.addEventListener('keyup',e=>keys[e.code]=false);document.addEventListener('contextmenu',e=>e.preventDefault());

