document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='KeyR')reload();if(e.code==='KeyE')pickup();});document.addEventListener('keyup',e=>keys[e.code]=false);document.addEventListener('contextmenu',e=>e.preventDefault());
const audioCtx=new (window.AudioContext||window.webkitAudioContext)();function sfx(freq=100,dur=.12,type='square',gain=.08){if(audioCtx.state==='suspended')audioCtx.resume();const osc=audioCtx.createOscillator(),amp=audioCtx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audioCtx.currentTime);osc.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.35),audioCtx.currentTime+dur);amp.gain.setValueAtTime(gain,audioCtx.currentTime);amp.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);osc.connect(amp);amp.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+dur);}
function reload(){if(!playing||reloading||ammo===12||reserve<=0)return;reloading=true;reloadTime=1.45;document.getElementById('reloadMsg').textContent='RECARREGANDO…';sfx(220,.11,'triangle',.04);setTimeout(()=>sfx(310,.09,'triangle',.035),420);}
function fire(){if(!playing||!document.pointerLockElement||shootCooldown>0||reloading)return;if(ammo<=0){sfx(110,.05,'square',.025);shootCooldown=.25;return;}ammo--;shootCooldown=.24;reloading=false;document.getElementById('reloadMsg').textContent='';muzzleFlash.intensity=18;setTimeout(()=>muzzleFlash.intensity=0,55);weapon.position.z=-.49;weapon.rotation.x=-.14;sfx(115,.16,'sawtooth',.09);sfx(650,.055,'triangle',.025);raycaster.setFromCamera(new THREE.Vector2(0,0),camera);const meshes=[];zombies.forEach(z=>{if(!z.userData.dead)z.traverse(o=>{if(o.isMesh)meshes.push(o);});});const hits=raycaster.intersectObjects(meshes,false);if(hits.length&&hits[0].distance<46){const z=zombies.find(a=>a===hits[0].object||a.children.includes(hits[0].object)||a.getObjectById(hits[0].object.id));if(z&&!z.userData.dead){z.userData.health-=hits[0].object.geometry.type==='SphereGeometry'&&hits[0].object.position.y>1.5?100:55;const hm=document.getElementById('hitmarker');hm.classList.add('show');setTimeout(()=>hm.classList.remove('show'),100);if(z.userData.health<=0)killZombie(z);else sfx(70,.08,'triangle',.04);}}ui();}
document.addEventListener('mousedown',e=>{if(e.button===0)fire();});
function killZombie(z){if(z.userData.dead)return;z.userData.dead=true;kills++;z.rotation.x=-Math.PI/2;z.position.y=.35;setTimeout(()=>{scene.remove(z);const i=zombies.indexOf(z);if(i>=0)zombies.splice(i,1);},1800);sfx(65,.22,'sawtooth',.05);const feed=document.getElementById('killfeed');feed.innerHTML=`<span style="color:#d8f36a">+ 01</span> INFECTADO ELIMINADO<br>`+feed.innerHTML;setTimeout(()=>{feed.innerHTML=feed.innerHTML.replace(/<span[^>]*>\+ 01<\/span> INFECTADO ELIMINADO<br>/,'');},2400);if(kills%4===0)dropAmmo(z.position.x,z.position.z);}
function dropAmmo(x,z){const g=new THREE.Group();const boxmesh=new THREE.Mesh(new THREE.BoxGeometry(.4,.25,.3),new THREE.MeshStandardMaterial({color:0x9ca66a,metalness:.3,roughness:.5,emissive:0x435025,emissiveIntensity:.7}));g.add(boxmesh);const glow=new THREE.PointLight(0xb9df5b,1.3,4);glow.position.y=.5;g.add(glow);g.position.set(x,.22,z);scene.add(g);pickups.push(g);}
function pickup(){if(!playing)return;for(let i=pickups.length-1;i>=0;i--){if(pickups[i].position.distanceTo(camera.position)<2.5){reserve=Math.min(96,reserve+12);scene.remove(pickups[i]);pickups.splice(i,1);document.getElementById('interact').classList.remove('show');ui();sfx(420,.12,'sine',.04);break;}}}
function endGame(){playing=false;gameOver=true;if(document.pointerLockElement)document.exitPointerLock();document.getElementById('endEyebrow').textContent=`RELATÓRIO FINAL · ${kills} AMEAÇAS NEUTRALIZADAS`;document.getElementById('endTitle').innerHTML='VOCÊ<br>CAIU.';document.getElementById('endCopy').innerHTML='A noite ainda não acabou.<br>Quantos você consegue levar com você?';document.getElementById('endScreen').classList.add('visible');}
function update(dt){if(!playing)return;shootCooldown=Math.max(0,shootCooldown-dt);if(reloading){reloadTime-=dt;if(reloadTime<=0){let take=Math.min(12-ammo,reserve);ammo+=take;reserve-=take;reloading=false;document.getElementById('reloadMsg').textContent='';ui();}}
const forward=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw)),right=new THREE.Vector3(Math.cos(yaw),0,-Math.sin(yaw));let move=new THREE.Vector3();if(keys.KeyW)move.add(forward);if(keys.KeyS)move.sub(forward);if(keys.KeyD)move.add(right);if(keys.KeyA)move.sub(right);let sprint=(keys.ShiftLeft||keys.ShiftRight)&&stamina>0&&move.lengthSq()>0;const speed=sprint?7.2:4.15;if(move.lengthSq()>0){move.normalize();camera.position.addScaledVector(move,speed*dt);walkTime+=dt*(sprint?13:8);weapon.position.y=-.29+Math.sin(walkTime)*.012;stamina=Math.max(0,stamina-(sprint?28:0)*dt);}else stamina=Math.min(100,stamina+18*dt);if(!sprint)weapon.position.y+=(-.29-weapon.position.y)*Math.min(1,dt*8);weapon.position.z+=(-.58-weapon.position.z)*Math.min(1,dt*12);weapon.rotation.x+=(-.04-weapon.rotation.x)*Math.min(1,dt*9);camera.position.x=THREE.MathUtils.clamp(camera.position.x,-7.2,7.2);camera.position.z=THREE.MathUtils.clamp(camera.position.z,-84,5);
let nearby=false;for(const p of pickups){p.rotation.y+=dt; if(p.position.distanceTo(camera.position)<2.4)nearby=true;}document.getElementById('interact').classList.toggle('show',nearby);
for(const z of zombies){if(z.userData.dead)continue;const dx=camera.position.x-z.position.x,dz=camera.position.z-z.position.z,dist=Math.hypot(dx,dz);z.rotation.y=Math.atan2(-dx,-dz);z.userData.phase+=dt*6;z.userData.arm1.rotation.x=Math.sin(z.userData.phase)*.24;z.userData.arm-1.rotation.x=-Math.sin(z.userData.phase)*.24;z.userData.leg1.rotation.x=Math.sin(z.userData.phase)*.42;z.userData.leg-1.rotation.x=-Math.sin(z.userData.phase)*.42;z.position.y=Math.abs(Math.sin(z.userData.phase))*0.025;if(dist>1.35){z.position.x+=dx/dist*z.userData.speed*dt;z.position.z+=dz/dist*z.userData.speed*dt;}else{z.userData.attack-=dt;if(z.userData.attack<=0){health-=9;z.userData.attack=1.2;document.getElementById('damageFlash').classList.add('on');setTimeout(()=>document.getElementById('damageFlash').classList.remove('on'),110);sfx(55,.15,'sawtooth',.07);ui();if(health<=0){health=0;ui();endGame();return;}}}}
if(zombies.length===0){wave++;reserve=Math.min(96,reserve+12);ammo=Math.min(12,ammo+3);spawnWave();ui();}if(zombies.length<Math.min(3+wave,8)&&spawnTimer<=0){makeZombie((rand()-.5)*12,-25-rand()*35);spawnTimer=2.8;}spawnTimer-=dt;}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);update(dt);renderer.render(scene,camera);}animate();
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
</script>

